command:
// Foundry VTT Macro: Источники сцены (ГМ)
// Задаёт уровень Масштаба Источника каждой доктрины для ТЕКУЩЕЙ сцены
// (флаг scene.flags.dedrel.sourceScale). Конструктор заклинаний предзаполняет
// селект источника этим уровнем; игроки не могут выбрать выше сценового.
// Доктрина без флага = без ограничений (уровень судит ГМ устно).
(async () => {
  if (!game.user.isGM) return ui.notifications.warn("Только для ГМа.");
  const scene = canvas.scene;
  if (!scene) return ui.notifications.warn("Нет активной сцены.");

  const magicCfg = CONFIG.DEDREL?.magic;
  if (!magicCfg) return ui.notifications.error("CONFIG.DEDREL.magic не загружен.");

  const current = scene.getFlag("dedrel", "sourceScale") || {};
  const scaleOptions = (selectedKey) => {
    const opts = [`<option value="" ${selectedKey === undefined || selectedKey === null ? "selected" : ""}>— не задано —</option>`];
    for (const [k, v] of Object.entries(magicCfg.sourceScales)) {
      opts.push(`<option value="${k}" ${selectedKey === k ? "selected" : ""}>${game.i18n.localize(v.label)}</option>`);
    }
    return opts.join("");
  };

  // Только доктрины, описанные в конфиге Конструктора
  const rows = Object.keys(magicCfg.doctrines).map(key => `
    <div class="form-group" style="display:flex; align-items:center; gap:10px; margin-bottom:6px;">
      <label style="flex: 1;">${game.i18n.localize(`DEDREL.Magic.Doctrines.${key}`)}</label>
      <select name="src-${key}" style="flex: 1;">${scaleOptions(current[key])}</select>
    </div>
  `).join("");

  const result = await foundry.applications.api.DialogV2.prompt({
    window: { title: `Источники сцены: ${scene.name}` },
    position: { width: 420 },
    content: `<p class="hint">Уровень источника каждой доктрины в этой локации.</p>${rows}`,
    ok: {
      label: "Сохранить",
      icon: "fa-solid fa-floppy-disk",
      callback: (event, button) => {
        const data = {};
        for (const key of Object.keys(magicCfg.doctrines)) {
          const value = button.form.elements[`src-${key}`]?.value;
          if (value) data[key] = value;
        }
        return data;
      }
    },
    rejectClose: false
  });

  if (result === null || result === undefined) return;
  // setFlag мержит объекты и не удаляет снятые ключи — заменяем объект целиком
  // оператором ForcedReplacement (V14, см. FOUNDRY V14 QUIRKS.md, раздел 14)
  await scene.update({ "flags.dedrel.sourceScale": _replace(result) });
  ui.notifications.info(`Источники сцены «${scene.name}» сохранены.`);
})();
